"""Mojo port of `src/textkit/`, generated by mojo-anything. Import this package where the code
imported the original module."""

from . import _native

import builtins as _builtins


def _call(f, *args):
    try:
        return f(*args)
    except Exception as e:
        # Mojo raises every error as `Exception`; `Name: message` names the exception to raise.
        if type(e) is not Exception:
            raise
        name, sep, message = str(e).partition(": ")
        cls = getattr(_builtins, name, None)
        if not (sep and isinstance(cls, type) and issubclass(cls, BaseException)):
            raise
        # Some builtins take several arguments (`UnicodeDecodeError`): use the nearest base
        # that takes a message alone.
        for base in cls.__mro__:
            try:
                error = base(message)
            except TypeError:
                continue
            raise error from None
        raise


def slugify(text, sep="-", max_length=None):
    return _call(_native.slugify, text, sep, max_length)


def word_counts(text, min_length=1):
    return _call(_native.word_counts, text, min_length)


def chunk(items, size):
    return _call(_native.chunk, items, size)


def page_count(total, per_page):
    return _call(_native.page_count, total, per_page)


def mean(values):
    return _call(_native.mean, values)


def clipped(text, limits=None):
    return _call(_native.clipped, text, limits)


# Not ported: these stay in Python and come from the original module.
_KEPT = {
    "Stack": "textkit.stack",
    "walk": "textkit.words",
    "apply": "textkit.words",
    "configure": "textkit.words",
    "Limits": "textkit.words",
}


def __getattr__(name):
    if name in _KEPT:
        import importlib

        try:
            module = importlib.import_module(_KEPT[name])
        except ImportError as error:
            raise AttributeError(
                f"{name!r} stays in Python, in {_KEPT[name]}, which cannot be imported: {error}"
            ) from error
        return getattr(module, name)
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")


__all__ = ["slugify", "word_counts", "chunk", "page_count", "mean", "clipped", "Stack", "walk", "apply", "configure", "Limits"]
